#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
 * Merge Sort - A recursive implementation of the Merge Sort algorithm.
 * 
 * This implementation uses a divide-and-conquer strategy:
 * 1. Divide the array into halves.
 * 2. Recursively sort each half.
 * 3. Merge the two sorted subarrays back together.
 * 
 * Time Complexity: O(n log n) on average
 * Space Complexity: O(n) for the auxiliary array used during merging
 * 
 * Note: This implementation does not use heap allocation or dynamic arrays.
 * It uses a fixed-size array for the partitioning.
 */

void quicksort(int arr[], int left, int right) {
    /* Base case: if the array has only one element, it's already sorted */
    if (left >= right) {
        return;
    }

    /* Choose a pivot element */
    int pivot = arr[left];

    /* Partition the array around the pivot */
    int i = left;
    int j = right;

    /* Move elements smaller than pivot to smaller indices */
    while (i < j) {
        /* Move elements larger than pivot to larger indices */
        if (arr[i] < pivot) {
            i++;
        } else if (arr[i] > pivot) {
            j--;
        }
    }

    /* Swap pivot with the element at the partition point */
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;

    /* Recursively sort the left and right subarrays */
    quicksort(arr, left, i - 1);
    quicksort(arr, i + 1, right);
}

/*
 * Example usage:
 * 
 * int main() {
 *     int arr[] = {3, 2, 1, 4, 5, 6};
